#!/bin/bash

# Exit on error
set -e

# 1. Hyprland実行チェック
if ! pgrep -x "Hyprland" > /dev/null; then
    echo "Error: Hyprland is not running." >&2
    exit 1
fi

# 2. パス設定
# スクリプトの場所を基準に相対パスで指定
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
OUTPUT_FILE_RELATIVE="../../dotfiles/hyprland/.config/hypr/bindings-overrides.conf"
OUTPUT_FILE="$(realpath "${SCRIPT_DIR}/${OUTPUT_FILE_RELATIVE}")"

echo "Generating bindings overrides to: ${OUTPUT_FILE}"

# 3. ヘッダー生成
cat << EOF > "${OUTPUT_FILE}"
# This file is automatically generated by update-bindings-overrides.
# Generated on: $(date)
# DO NOT EDIT THIS FILE MANUALLY.

EOF

# 4. キーバインドの自動変換 (Core Logic)
# 修正点: .key が空の場合は code:xxx を使用するように変更
hyprctl binds -j | jq -r '
  .[] |
  select((.modmask / 64 | floor % 2 == 1) and (.modmask / 8 | floor % 2 == 0)) |
  (
    (if (.modmask / 1 | floor % 2 == 1) then "SHIFT" else "" end) +
    (if (.modmask / 4 | floor % 2 == 1) then "CTRL" else "" end)
  ) as $mods_raw |
  (
    "" +
    (if (.modmask / 1 | floor % 2 == 1) then "SHIFT " else "" end) +
    (if (.modmask / 4 | floor % 2 == 1) then "CTRL " else "" end)
  ) as $mods |

  # --- 修正: キー名安全化ロジック ---
  # キー名が存在し、長さが1以上ならそれを使う。ダメならキーコードを使う。
  (if (.key and (.key | length > 0)) then .key else "code:" + (.keycode | tostring) end) as $safe_key |

  (
    "\($mods_raw)_\($safe_key)_1_unbind unbind = SUPER \($mods), \($safe_key)\n" +
    "\($mods_raw)_\($safe_key)_2_bind bind = ALT \($mods), \($safe_key), \(.dispatcher), \(.arg)"
  )
' | sort -u | awk '
  {
    # ソート用キーを抽出（最初のスペースまで）
    key = $1
    base_key = key
    sub(/_[12]_(unbind|bind)$/, "", base_key)

    # ソート用キーを削除
    $1 = ""
    sub(/^ /, "")

    # 前のベースキーと異なる場合（かつ最初ではない場合）、空行を挿入
    if (prev_base_key != "" && prev_base_key != base_key) {
      print ""
    }
    print $0
    prev_base_key = base_key
  }
  END { if (NR > 0) print "" }
' >> "${OUTPUT_FILE}"

# 5. 手動修正 (Manual Fixes)
cat << EOF >> "${OUTPUT_FILE}"

# Manual Fixes
unbind = SUPER , space
bind = ALT , space, exec, rofi -show drun

unbind = SUPER , escape
bind = ALT , escape, exec, wlogout
EOF

echo "Done."